def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.25))

    needy_count = 1
    dangerous = 0
    rich_live = 0
    max_prev_bid = 0.0
    urgent_opp = 0

    for opp in alive:
        req = opp.get('water_requirement', WATER_REQ)
        if req > 0:
            needy_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 8:
            rich_live += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            pbid = prev.get('bid')
            if pbid is not None:
                max_prev_bid = max(max_prev_bid, float(pbid))
        if opp.get('budget', 0) > budget and opp.get('hp', 10) > 3:
            dangerous += 1

    expected_share = supply / float(max(1, needy_count))
    severe_shortage = supply < WATER_REQ * 1.35
    moderate_shortage = supply < WATER_REQ * 1.7
    abundant = supply >= WATER_REQ * 2.0

    survival_mode = hp <= 3 or no_water >= 1
    critical_mode = hp <= 2 or no_water >= 2

    if critical_mode:
        bid = max(DAILY_SALARY * 0.95, max_prev_bid + 2.0)
    elif survival_mode:
        if severe_shortage:
            bid = max(DAILY_SALARY * 0.82, max_prev_bid + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.68, min(max_prev_bid + 1.0, DAILY_SALARY * 0.9))
    else:
        if abundant and hp >= 6:
            bid = DAILY_SALARY * 0.18
        elif moderate_shortage:
            bid = DAILY_SALARY * 0.42
        else:
            bid = DAILY_SALARY * 0.28

        if max_prev_bid >= DAILY_SALARY * 1.2:
            bid = min(bid, DAILY_SALARY * 0.35)
        elif max_prev_bid >= DAILY_SALARY * 0.9:
            bid = max(bid, DAILY_SALARY * 0.38)
        elif max_prev_bid > 0:
            bid = max(bid, min(max_prev_bid + 1.0, DAILY_SALARY * 0.62))

    if rich_live >= 1 and not survival_mode:
        bid *= 0.92
    if dangerous >= 2 and severe_shortage:
        bid *= 1.08
    if urgent_opp >= 2 and not survival_mode:
        bid *= 0.9
    if expected_share < WATER_REQ * 0.55:
        bid *= 1.12

    if day >= 8 and hp >= 6 and not severe_shortage:
        bid *= 0.85

    reserve_floor = 0.0
    if hp > 3:
        reserve_floor = DAILY_SALARY * max(0, 10 - day) * 0.18
    max_affordable = max(0.0, budget - reserve_floor)
    if critical_mode:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append((float(b), oid))
            except Exception:
                pass

    highest_prev_bid = max([b for b, _ in prev_bids], default=0.0)
    top_prev_bidder_id = None
    if prev_bids:
        top_prev_bidder_id = max(prev_bids, key=lambda x: x[0])[1]

    # Base bid: aim for securing water without matching aggressive tops
    # If supply is higher, we can bid slightly less because allocation is easier.
    supply_factor = 1.0
    if supply <= MIN_SUPPLY:
        supply_factor = 1.0
    elif supply >= MAX_SUPPLY:
        supply_factor = 0.85
    else:
        # linear interpolate between 1.0 at 15 and 0.85 at 25
        supply_factor = 1.0 - 0.15 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # Pressure estimate from yesterday
    pressure_tier = 0
    if highest_prev_bid >= DAILY_SALARY * 1.6:
        pressure_tier = 3
    elif highest_prev_bid >= DAILY_SALARY * 1.0:
        pressure_tier = 2
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        pressure_tier = 1

    # If Alex/Eric were top bidders yesterday, they likely continue bidding high.
    # We undercut slightly to win price-efficiently.
    undercut = 0.92
    if top_prev_bidder_id in ('Alex', 'Eric'):
        undercut = 0.90
    elif top_prev_bidder_id is not None:
        undercut = 0.93

    # Emergency scaling based on my HP/no_water_days
    urgency = 0.0
    if my_hp <= 2:
        urgency = 1.0
    elif my_hp <= 3:
        urgency = 0.75
    elif my_hp <= 4:
        urgency = 0.55
    else:
        urgency = 0.35

    if my_no_water_days >= 2:
        urgency = max(urgency, 0.85)

    # Choose target bid level
    # Mid-high strategy: start around 0.55-0.75 salary, adjust by pressure tier and urgency.
    base = DAILY_SALARY * (0.55 + 0.1 * pressure_tier)  # 0.55..0.85
    target = base * supply_factor * undercut

    # If pressure was very high, increase but still try to avoid matching the top.
    if pressure_tier >= 2:
        target = max(target, DAILY_SALARY * 0.72 * supply_factor * undercut)
    if pressure_tier >= 3:
        target = max(target, DAILY_SALARY * 0.85 * supply_factor * undercut)

    # Apply urgency
    target = target * (0.85 + 0.3 * urgency)  # roughly 0.85..1.15

    # Cap by budget and keep non-negative
    bid = max(0.0, min(my_budget, target))

    # If we are extremely healthy and supply is high, reduce further to save budget.
    if my_hp >= 6 and supply >= 20:
        bid = min(bid, DAILY_SALARY * 0.6)

    # If we are in danger, ensure we bid enough to likely secure water.
    if my_hp <= 3 or my_no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.75 * supply_factor)
        bid = min(bid, my_budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQ = 13
    MY_DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], MY_DAILY_SALARY * 0.1)

    yesterday_bids = []
    total_opponent_water_req = 0
    for opp in alive_opponents:
        total_opponent_water_req += opp['water_requirement']
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    total_demand = MY_WATER_REQ + total_opponent_water_req

    base_bid = MY_DAILY_SALARY * 0.55 

    if my_status['hp'] <= 2: 
        base_bid = MY_DAILY_SALARY * 0.95 
    elif my_status['hp'] <= 4: 
        base_bid = MY_DAILY_SALARY * 0.85 

    if my_status['no_water_days'] > 0:
        base_bid = max(base_bid, MY_DAILY_SALARY * 0.9) 

    if day_context['day'] >= EPISODE_DAYS - 2: 
        base_bid = max(base_bid, MY_DAILY_SALARY * 0.9) 
    elif day_context['day'] >= EPISODE_DAYS - 4: 
        base_bid = max(base_bid, MY_DAILY_SALARY * 0.75)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= MY_DAILY_SALARY * 0.8: 
            if my_status['hp'] <= 3: 
                base_bid = max(base_bid, highest_prev_bid + 5) 
            else: 
                base_bid = max(base_bid, highest_prev_bid * 0.95) 
        elif highest_prev_bid >= MY_DAILY_SALARY * 0.5: 
            base_bid = max(base_bid, highest_prev_bid + 1) 
        else: 
            if my_status['hp'] > 5:
                base_bid = min(base_bid, MY_DAILY_SALARY * 0.4) 
            else:
                base_bid = max(base_bid, MY_DAILY_SALARY * 0.6) 

    if total_demand > 0: 
        supply_demand_ratio = day_context['supply'] / total_demand

        if supply_demand_ratio >= 1.5: 
            if my_status['hp'] > 5: 
                base_bid *= 0.8
            else: 
                base_bid *= 0.9
        elif supply_demand_ratio < 1.0: 
            base_bid *= 1.15 
            if my_status['hp'] <= 4:
                base_bid *= 1.1 
        elif supply_demand_ratio < 1.2: 
            base_bid *= 1.05 

    final_bid = min(my_status['budget'], base_bid)
    final_bid = max(final_bid, 1.0) 

    return round(final_bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    budget = my_status['budget']
    hp = my_status['hp']
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # base strategy: if we have yesterday bids, use their average
    if yesterday_bids:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        # adjust based on health
        if hp <= 2:
            # survival: bid up to 90% of salary but not more than budget
            target = min(budget, DAILY_SALARY * 0.9)
        elif hp <= 4:
            target = min(budget, max(DAILY_SALARY * 0.7, avg_bid * 0.8))
        else:
            # healthy: try to save money, bid slightly above average to win
            target = min(budget, max(DAILY_SALARY * 0.5, avg_bid * 1.1))
        return min(budget, target)

    # no history: default bid based on health
    if hp <= 2:
        return min(budget, DAILY_SALARY * 0.9)
    elif hp <= 4:
        return min(budget, DAILY_SALARY * 0.7)
    else:
        return min(budget, DAILY_SALARY * 0.5)
